} Cursor pagination: # First page
curl -s -X POST http://localhost:9400/api/fuse/query \ -H 'Content-Type: application/json' \ -d '{"query": "SELECT * FROM cluster_a.application_logs ORDER BY timestamp DESC", "page_size": 10}' { "columns": ["timestamp", "service", "status"], "rows": [["2026-04-10T05:30:00Z", "api-gateway", 200], "..."], "metadata": {"total_rows": 10}, "next_cursor": "eyJvZmZzZXQiOjEwfQ=="
