This is the core of your connector. The SubQuery struct contains: pub struct SubQuery { pub table: String, // "users" pub projections: Vec<String>, // ["id", "name"] or [] for all pub filter: Option<FilterExpr>, // WHERE clause tree pub aggregations: Vec<AggregationExpr>, pub group_by: Vec<String>, pub sort: Vec<SortExpr>, pub limit: Option<u64>, pub passthrough: Option<Value>, // connector-specific raw data
} Translate each field you support into your native query. Example for a SQL-based datasource: fn subquery_to_sql(sq: &SubQuery) -> String { let cols = if sq.projections.is_empty() { "*".to_string() } else { sq.projections.join(", ") }; let mut sql = format!("SELECT {} FROM {}", cols, sq.table); if let Some(filter) = &sq.filter { sql.push_str(&format!(" WHERE {}", filter_to_sql(filter))); } if !sq.group_by.is_empty() { sql.push_str(&format!(" GROUP BY {}", sq.group_by.join(", "))); } if !sq.sort.is_empty() { let clauses: Vec<String> = sq.sort.iter() .map(|s| format!("{} {}", s.field, if s.descending { "DESC" } else { "ASC" })) .collect(); sql.push_str(&format!(" ORDER BY {}", clauses.join(", "))); } if let Some(limit) = sq.limit { sql.push_str(&format!(" LIMIT {}", limit)); } sql
}

