FilterExpr is a recursive enum. Translate it to your native filter format: fn filter_to_sql(expr: &FilterExpr) -> String { match expr { FilterExpr::Comparison { field, op, value } => { let op_str = match op { ComparisonOp::Eq => "=", ComparisonOp::Ne => "!=", ComparisonOp::Gt => ">", ComparisonOp::Gte => ">=", ComparisonOp::Lt => "<", ComparisonOp::Lte => "<=", ComparisonOp::Like => "LIKE", ComparisonOp::ILike => "ILIKE", }; format!("{} {} {}", field, op_str, scalar_to_sql(value)) } FilterExpr::And(left, right) => format!("({} AND {})", filter_to_sql(left), filter_to_sql(right)), FilterExpr::Or(left, right) => format!("({} OR {})", filter_to_sql(left), filter_to_sql(right)), FilterExpr::Not(inner) => format!("NOT ({})", filter_to_sql(inner)), FilterExpr::In { field, values } => { let vals: Vec<String> = values.iter().map(scalar_to_sql).collect(); format!("{} IN ({})", field, vals.join(", ")) } FilterExpr::IsNull(field) => format!("{} IS NULL", field), FilterExpr::IsNotNull(field) => format!("{} IS NOT NULL", field), }
} fn scalar_to_sql(v: &ScalarValue) -> String { match v { ScalarValue::Int64(n) => n.to_string(), ScalarValue::Float64(f) => f.to_string(), ScalarValue::Utf8(s) => format!("'{}'", s.replace('\'', "''")), ScalarValue::Boolean(b) => b.to_string(), }
} For non-SQL datasources, translate to your native format instead. See these real examples: OpenSearch → Query DSL JSON: crates/fuse-connectors/opensearch/src/pushdown.rs DynamoDB → FilterExpression + KeyConditionExpression: crates/fuse-connectors/dynamodb/src/lib.rs MongoDB → BSON query document: crates/fuse-connectors/mongodb/src/lib.rs

