Build your own connector using fuse-connector-sdk. See the connector authoring guide . Implement two traits: #[async_trait]
pub trait FederatedConnector: Send + Sync + Debug { fn id(&self) -> &str; fn connector_type(&self) -> &str; fn capabilities(&self) -> ConnectorCapabilities; async fn health_check(&self) -> ConnectorHealth; async fn discover_schemas(&self) -> Result<Vec<SchemaInfo>>; async fn get_schema(&self, table: &str) -> Result<Schema>; async fn execute(&self, query: &SubQuery) -> Result<Vec<RecordBatch>>; async fn execute_streaming(&self, query: &SubQuery, tx: Sender<...>);
} pub trait ConnectorFactory: Send + Sync { fn connector_type(&self) -> &str; fn create(&self, config: &ConnectorConfig) -> Result<Arc<dyn FederatedConnector>>;
} Register your factory in main.rs and add a [[connector]] block to fuse.toml. See crates/fuse-connectors/example/ for a minimal working template.
